# Run elevated. Read-only. Requires Windows Server 2019+ with NTLM enhanced auditing.
$servers = @($env:COMPUTERNAME)   # or: Get-Content .\servers.txt
$SIGN = 0x10; $KEYX = 0x40000000

$rows = foreach ($s in $servers) {
  Get-WinEvent -ComputerName $s -FilterHashtable @{ LogName='Microsoft-Windows-NTLM/Operational'; Id=4022,4023 } -ErrorAction SilentlyContinue |
  ForEach-Object {
    $m = $_.Message
    $f = if ($m -match 'Negotiated Flags:\s+(0x[0-9A-Fa-f]+)') { [Convert]::ToInt64($Matches[1],16) } else { $null }
    if ($null -ne $f -and -not ($f -band $SIGN)) {
      [pscustomobject]@{
        Server     = $s
        EventId    = $_.Id
        LastSeen   = $_.TimeCreated
        ClientIP   = if ($m -match 'Client IP:\s+(\S+)')        { $Matches[1] } else { '-' }
        ClientHost = if ($m -match 'Client Machine:\s+(\S+)')   { $Matches[1] } else { '-' }
        User       = if ($m -match 'Username:\s+(\S+)')         { $Matches[1] } else { '-' }
        Process    = if ($m -match 'Process Name:\s+(.+)')       { $Matches[1].Trim() } else { '-' }
        KeyExch    = [bool]($f -band $KEYX)
        Flags      = ('0x{0:X8}' -f $f)
      }
    }
  }
}

$rows | Sort-Object LastSeen -Descending |
  Sort-Object Server, ClientIP, Process -Unique |
  Export-Csv .\ntlm-unsigned-clients.csv -NoTypeInformation
"{0} unsigned client/process combinations written to ntlm-unsigned-clients.csv" -f @($rows | Sort-Object Server, ClientIP, Process -Unique).Count
